return {["fb06_01"]={["BgmDown"]=1,["dsc"]=[[这里是一间不大的木头屋子，但是麻雀虽小，五藏俱全，屋子中只是疏疏落落地摆着几件家具，所以也不显得怎么小。]],["enterable"]=1,["id"]=[[fb06_01]],["item1"]=[[fb06item4]],["item2"]=[[fb06item8]],["name"]=[[木屋]],["permission"]=2,["role1"]=[[fb06r01_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb06_04]],["visible"]=1},["fb06_02"]={["BgmDown"]=1,["dsc"]=[[这里也是一间木屋，屋子中的摆设什么简单，但是却有很多工具，锯子啦，刨子啦，锤子啦，还有满地的木屑，一看就知道是一个工匠的家。看！我们的巧匠正忙着呢，不过不知道他又在做什么呢？]],["enterable"]=1,["id"]=[[fb06_02]],["item1"]=[[21zstrigger01]],["name"]=[[工匠屋]],["permission"]=2,["role1"]=[[fb06r02_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb06_05]],["visible"]=1},["fb06_03"]={["BgmDown"]=1,["dsc"]=[[这里是树林中的一间小小的酒家，地方虽然不大，但是也有不少习武弟子光顾这里。你终于找到香味的来源了，看着可口的饭菜，你忍不住也想叫一份了。]],["enterable"]=1,["id"]=[[fb06_03]],["item1"]=[[bfitem1]],["item2"]=[[mybritem1]],["item3"]=[[ssydj]],["item4"]=[[mjwcjc]],["name"]=[[酒家]],["permission"]=2,["role1"]=[[fb06r03_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb06_07]],["visible"]=1},["fb06_04"]={["down"]=[[fb06_01]],["dsc"]=[[这是一条从南到北的林间小道，沿途风景极之清幽，参天古树，拔地而起，两旁百花争艳。令人留连忘返。]],["enterable"]=1,["fightBackground"]=[[森林外]],["id"]=[[fb06_04]],["name"]=[[林间小道]],["permission"]=2,["role1"]=[[ever04_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb06_09]],["visible"]=1},["fb06_05"]={["down"]=[[fb06_02]],["dsc"]=[[这是一条用木板铺成的小道，虽然不是很长，但是却看得出铺得十分细心。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb06_05]],["name"]=[[木板路]],["permission"]=2,["role1"]=[[fb06r05_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb06_10]],["visible"]=1},["fb06_06"]={["BgmDown"]=1,["dsc"]=[[这是一间在树林中的小屋，屋子中间摆着几张大床，几张桌子，看来是个休息的地方，室中光线柔和，使人更增睡意。]],["enterable"]=1,["fightBackground"]=[[村庄室内]],["id"]=[[fb06_06]],["name"]=[[小屋]],["permission"]=2,["right"]=[[fb06_07]],["role1"]=[[fb06r06_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb06_07"]={["down"]=[[fb06_03]],["dsc"]=[[这是一条长长的林间小道，从东边一直通到西边，一眼望去，看不到路的尽头。两旁百花争艳。令人留连忘返。南边好像有香味散发出来，北边是个兵器房。]],["enterable"]=1,["fightBackground"]=[[森林外]],["id"]=[[fb06_07]],["left"]=[[fb06_06]],["name"]=[[林间小道]],["permission"]=1,["right"]=[[fb06_08]],["role1"]=[[cfitem1]],["role2"]=[[cg2item1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb06_11]],["visible"]=1},["fb06_08"]={["down"]=[[fb06_62]],["dsc"]=[[这是一条长长的林间小道，从东边一直通到西边，一眼望去，看不到路的尽头。两旁百花争艳。令人留连忘返。]],["enterable"]=1,["fightBackground"]=[[森林外]],["id"]=[[fb06_08]],["item1"]=[[2020znqrwdj01]],["left"]=[[fb06_07]],["name"]=[[林间小道]],["permission"]=1,["right"]=[[fb06_09]],["role1"]=[[cfitem2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb06_09"]={["BgmDown"]=1,["down"]=[[fb06_04]],["dsc"]=[[这里是树林中的一片比较大的空地，名曰:青草坪。因为处于密林之中所以这里平时很少有人来，但是不知道为什么，这里却经常有人迹出现。你看，又一个来了。]],["enterable"]=1,["fightBackground"]=[[青草坪]],["id"]=[[fb06_09]],["left"]=[[fb06_08]],["name"]=[[青草坪]],["permission"]=1,["right"]=[[fb06_10]],["role1"]=[[fb06r09_1c]],["role2"]=[[cfitem3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb06_12]],["visible"]=1},["fb06_10"]={["BgmDown"]=1,["down"]=[[fb06_05]],["dsc"]=[[这是一条长长的林间小道，从东边一直通到西边，一眼望去，看不到路的尽头。两旁百花争艳。令人留连忘返。]],["enterable"]=1,["fightBackground"]=[[森林外]],["id"]=[[fb06_10]],["item1"]=[[21xcdfwp]],["item2"]=[[21zstrigger02]],["item3"]=[[21zstrigger03]],["item4"]=[[sy3chufa02]],["left"]=[[fb06_09]],["name"]=[[林间小道]],["permission"]=2,["right"]=[[fb06_15]],["stepMusic"]=[[jiaobu]],["up"]=[[fb06_13]],["visible"]=1},["fb06_11"]={["BgmDown"]=1,["down"]=[[fb06_07]],["dsc"]=[[这里是树林深处的一间小石屋，看来是打造兵器的，屋子中有个大火炉好烫的呢，屋中还有一张石几，上面放在一些已经打造好的兵器。]],["enterable"]=1,["id"]=[[fb06_11]],["name"]=[[打铁屋]],["permission"]=2,["role1"]=[[fb06r11_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb06_22]],["visible"]=1},["fb06_12"]={["BgmDown"]=1,["down"]=[[fb06_09]],["dsc"]=[[这是一条从南到北的林间小道，沿途风景极之清幽，参天古树，拔地而起，两旁百花争艳。令人留连忘返。]],["enterable"]=1,["fightBackground"]=[[森林外]],["id"]=[[fb06_12]],["name"]=[[林间小道]],["permission"]=2,["role1"]=[[jinianwanjia]],["stepMusic"]=[[jiaobu]],["up"]=[[fb06_14]],["visible"]=1},["fb06_13"]={["BgmDown"]=1,["down"]=[[fb06_10]],["dsc"]=[[这是树林中的一间石屋，屋内显得什么清净和简朴，房间中并没有什么特别的摆设在这里，不会受到任何东西的骚扰，是个修炼内功的好地方。]],["enterable"]=1,["id"]=[[fb06_13]],["name"]=[[石屋]],["permission"]=2,